#!/usr/bin/env python3
"""taxonomy.md from coverage-matrix.csv and data/derived/registry-tags.csv (auto-generated tables + hand-written notes appended from taxonomy-notes.md)."""
import csv, collections, os, json, glob
ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..')
cov = list(csv.DictReader(open(os.path.join(ROOT, 'coverage-matrix.csv'), encoding='utf-8')))
reg = list(csv.DictReader(open(os.path.join(ROOT, 'data', 'derived', 'registry-tags.csv'), encoding='utf-8')))
def cnt(rows, k):
    return collections.Counter(r[k] for r in rows)
def tbl(title, c, top=None):
    s = '\n### %s\n| value | cards |\n|---|---|\n' % title
    for k, v in c.most_common(top):
        s += '| %s | %d |\n' % (k or '(empty)', v)
    return s
o = '# Taxonomy and coverage of the captured set (paid tier, 2026-10-03)\n\nAuto-generated by `analysis/make_taxonomy.py` from `coverage-matrix.csv` and `data/derived/registry-tags.csv`; notes in the last section are manual.\n\nCards: %d (full access: 487 company cards + ABNB; 60 more tickers appear in the screener universe of 547 without a card).\n' % len(reg)
o += tbl('Basket (Gate 0 registry key from the screener filter)', cnt(reg, 'basket'))
o += tbl('Business type (predictability tag)', cnt(reg, 'business_type'))
o += tbl('Moat tag', cnt(reg, 'moat'))
o += tbl('AI risk tag', cnt(reg, 'ai_risk'))
o += tbl('Market-share trend tag', cnt(reg, 'market_share_trend'))
o += tbl('Growth source tag', cnt(reg, 'growth_source'))
o += tbl('Capex funding tag', cnt(reg, 'capex_funding'))
o += tbl('Margin trend', cnt(reg, 'margin_trend'))
o += tbl('Verdict (headline word)', cnt(reg, 'verdict'))
o += tbl('Shadow verdict', cnt(reg, 'shadow'))
o += tbl('Level', cnt(reg, 'level'))
o += tbl('Price word', cnt(reg, 'price_word'))
o += tbl('Review state', cnt(reg, 'review_state'))
o += '\n### Index membership\n| index | cards |\n|---|---|\n| S&P 500 | %d |\n| Nasdaq 100 | %d |\n' % (sum(int(r['sp500']) for r in reg), sum(int(r['nasdaq100']) for r in reg))
sub = collections.Counter(s for r in reg for s in r['subsectors'].split(';') if s)
o += tbl('Sub-sector (top 40)', sub, 40)
o += '\n### Cross-tab: basket x verdict\n'
ct = collections.defaultdict(collections.Counter)
for r in reg:
    ct[r['basket'] or '(none)'][r['verdict']] += 1
verd = sorted({r['verdict'] for r in reg})
o += '| basket | ' + ' | '.join(verd) + ' |\n|---|' + '---|' * len(verd) + '\n'
for b, c in sorted(ct.items()):
    o += '| %s | ' % b + ' | '.join(str(c.get(v, 0)) for v in verd) + ' |\n'
notes = os.path.join(ROOT, 'analysis', 'taxonomy-notes.md')
if os.path.exists(notes):
    o += '\n' + open(notes, encoding='utf-8').read()
open(os.path.join(ROOT, 'taxonomy.md'), 'w', encoding='utf-8').write(o)
print(len(o), 'chars')
